+            return TextFileBasedViolationStore::descriptionFileName;
+        }
+
+        try {
+            Class<?> strategyClass = Class.forName(configured);
+            if (!Modifier.isPublic(strategyClass.getModifiers())
+                    || !RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new IllegalArgumentException("not a public RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate RuleViolationFileNameStrategy configured by %s='%s'; it must be a public "
+                            + "RuleViolationFileNameStrategy with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private static String descriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD.matcher(description);
+        String lastWord = null;
+        while (matcher.find()) {
+            lastWord = matcher.group();
+        }
+        if (lastWord == null) {
+            lastWord = "rule";
+        }
+        return lastWord + "-" + shortDescriptionHash(description);
+    }
+
+    private static String shortDescriptionHash(String description) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder();
+            for (int i = 0; i < 8; i++) {
+                result.append(String.format("%02x", digest[i] & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private StoreState getStoreState(File storedRulesFile) {
+        try {
+            String path = storedRulesFile.getCanonicalPath();
+            return STORE_STATES.computeIfAbsent(path, ignored -> new StoreState(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadOrCreateIndex(StoreState state, IntegrityMode integrity) {
+        Path folder = storeFolder.toPath();
+        Path index = state.indexFile.toPath();
+        boolean indexExists = Files.exists(index, LinkOption.NOFOLLOW_LINKS);
+
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        ensureFolder(folder);
+
+        if (Files.exists(index, LinkOption.NOFOLLOW_LINKS)) {
+            if (!Files.isRegularFile(index, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Violation store index %s is not a regular file directly in the store folder",
+                        index.toAbsolutePath()));
+            }
+            return loadRulesFrom(index.toFile());
+        }
+
+        // A fail-mode check must be able to reject an absent index without creating it first.
+        if (integrity == IntegrityMode.FAIL) {
+            Properties empty = new Properties();
+            IntegrityAnalysis analysis = analyze(empty);
+            if (analysis.hasProblems()) {
+                throw new StoreInitializationFailedException(analysis.failureReport());
+            }
+        }
+
+        try {
+            Files.createFile(index);
+            return new Properties();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void ensureFolder(Path folder) {
+        try {
+            if (Files.exists(folder, LinkOption.NOFOLLOW_LINKS)) {
+                if (!Files.isDirectory(folder, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Violation store path %s is not a directory", folder.toAbsolutePath()));
+                }
+            } else {
+                Files.createDirectories(folder);
+            }
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadRulesFrom(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+            return result;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        StoreState state = initializedState();
+        synchronized (state.lock) {
+            return state.properties.containsKey(normalize(rule.getDescription()));
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        StoreState state = initializedState();
+        synchronized (state.lock) {
+            String description = normalize(rule.getDescription());
+            String recordedName = state.properties.getProperty(description);
+
+            if (integrityRepair && violations.isEmpty()) {
+                if (recordedName == null) {
+                    return;
+                }
+                forgetResolvedRule(description, recordedName, state);
+                return;
+            }
+
+            if (recordedName == null) {
+                String newName = nameFor(rule.getDescription());
+                Path destination = validateNewFileDestination(newName);
+                writeAtomically(destination, encodedViolations(violations), false);
+                state.properties.setProperty(description, normalize(newName));
+                try {
+                    syncProperties(state);
+                } catch (RuntimeException e) {
+                    deleteQuietly(destination);
+                    state.properties.remove(description);
+                    throw e;
+                }
+                return;
+            }
+
+            FileResolution resolution = resolve(recordedName);
+            Path destination = validateExistingFileDestination(recordedName, resolution);
+            writeAtomically(destination, encodedViolations(violations), true);
+        }
+    }
+
+    private void forgetResolvedRule(String description, String recordedName, StoreState state) {
+        FileResolution resolution = resolve(recordedName);
+        if (resolution.isUnsafeForUpdate()) {
+            throw unsafeUpdate(recordedName);
+        }
+
+        if (!sharesFileWithAnotherEntry(description, resolution, state.properties)) {
+            deleteEntryFile(resolution);
+        }
+
+        Object old = state.properties.remove(description);
+        try {
+            syncProperties(state);
+        } catch (RuntimeException e) {
+            if (old != null) {
+                state.properties.put(description, old);
+            }
+            throw e;
+        }
+    }
+
+    private boolean sharesFileWithAnotherEntry(String description, FileResolution resolution, Properties properties) {
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = properties.getProperty(otherDescription);
+            if (normalize(otherName).equals(normalize(resolution.recordedName))) {
+                return true;
+            }
+            FileResolution other = resolve(otherName);
+            if (resolution.isRegular() && other.isRegular()
+                    && resolution.realPath.equals(other.realPath)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void deleteEntryFile(FileResolution resolution) {
+        try {
+            if (resolution.isRegular()) {
+                Files.deleteIfExists(resolution.realPath);
+                if (resolution.isSymbolicLink()) {
+                    Files.deleteIfExists(resolution.recordedPath);
+                }
+            } else if (resolution.recordedPath != null) {
+                Files.deleteIfExists(resolution.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private Path validateNewFileDestination(String name) {
+        if (name == null || name.trim().isEmpty()) {
+            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
+        }
+        Path destination = destinationPath(name);
+        if (!isDirectPathInsideFolder(destination) || STORED_RULES_FILE_NAME.equals(name)
+                || Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
+            throw unsafeUpdate(name);
+        }
+        return destination;
+    }
+
+    private Path validateExistingFileDestination(String recordedName, FileResolution resolution) {
+        if (STORED_RULES_FILE_NAME.equals(recordedName) || resolution.isUnsafeForUpdate()) {
+            throw unsafeUpdate(recordedName);
+        }
+        return resolution.realPath != null ? resolution.realPath : resolution.recordedPath;
+    }
+
+    private StoreUpdateFailedException unsafeUpdate(String name) {
+        return new StoreUpdateFailedException(String.format(
+                "Refusing to update violation store file '%s': it is not a regular file directly in the store folder "
+                        + "owned by this rule", name));
+    }
+
+    private String nameFor(String description) {
+        String name = activeStrategy.createRuleFileName(description);
+        if (name == null || name.trim().isEmpty()) {
+            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
+        }
+        return name;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        StoreState state = initializedState();
+        synchronized (state.lock) {
+            String ruleDetailsFileName = state.properties.getProperty(normalize(rule.getDescription()));
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        try {
+            String text = new String(Files.readAllBytes(storeFolder.toPath().resolve(ruleDetailsFileName)), UTF_8);
+            return parseViolations(text);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private List<String> parseViolations(String text) {
+        List<String> result = new ArrayList<>();
+        StringBuilder current = new StringBuilder();
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character != '\r' && character != '\n') {
+                current.append(character);
+                continue;
+            }
+
+            int backslashes = 0;
+            for (int j = current.length() - 1; j >= 0 && current.charAt(j) == '\\'; j--) {
+                backslashes++;
+            }
+            if ((backslashes & 1) == 1) {
+                current.deleteCharAt(current.length() - 1);
+                current.append(character);
+                continue;
+            }
+
+            String violation = decodeEscapes(current.toString());
+            if (!violation.isEmpty()) {
+                result.add(violation);
+            }
+            current.setLength(0);
+            if (character == '\r' && i + 1 < text.length() && text.charAt(i + 1) == '\n') {
+                i++;
+            }
+        }
+        String violation = decodeEscapes(current.toString());
+        if (!violation.isEmpty()) {
+            result.add(violation);
+        }
+        return result;
+    }
+
+    private String decodeEscapes(String value) {
+        StringBuilder result = new StringBuilder();
+        for (int i = 0; i < value.length(); i++) {
+            char character = value.charAt(i);
+            if (character == '\\' && i + 1 < value.length() && value.charAt(i + 1) == '\\') {
+                result.append('\\');
+                i++;
+            } else {
+                result.append(character);
+            }
+        }
+        return result.toString();
+    }
+
+    private byte[] encodedViolations(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            for (int i = 0; i < violation.length(); i++) {
+                char character = violation.charAt(i);
+                if (character == '\\') {
+                    builder.append("\\\\");
+                } else if (character == '\r' || character == '\n') {
+                    builder.append('\\').append(character);
+                } else {
+                    builder.append(character);
+                }
+            }
+            builder.append('\n');
+        }
+        return builder.toString().getBytes(UTF_8);
+    }
+
+    private void writeAtomically(Path destination, byte[] contents, boolean replace) {
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-store-", ".tmp");
+            Files.write(temporary, contents, StandardOpenOption.TRUNCATE_EXISTING);
+            if (replace) {
+                moveReplacing(temporary, destination);
+            } else {
+                Files.move(temporary, destination);
+            }
+            temporary = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporary != null) {
+                deleteQuietly(temporary);
+            }
+        }
+    }
+
+    private void moveReplacing(Path source, Path destination) throws IOException {
+        try {
+            Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+        } catch (java.nio.file.AtomicMoveNotSupportedException e) {
+            Files.move(source, destination, StandardCopyOption.REPLACE_EXISTING);
+        }
+    }
+
+    private void syncProperties(StoreState state) {
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-index-", ".tmp");
+            try (java.io.OutputStream output = Files.newOutputStream(temporary, StandardOpenOption.TRUNCATE_EXISTING)) {
+                state.properties.store(output, "");
+            }
+            moveReplacing(temporary, state.indexFile.toPath());
+            temporary = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporary != null) {
+                deleteQuietly(temporary);
+            }
+        }
+    }
+
+    private FileResolution resolve(String recordedName) {
+        Path folderAbsolute = storeFolder.toPath().toAbsolutePath().normalize();
+        try {
+            Path folderReal = storeFolder.toPath().toRealPath();
+            Path recordedPath = destinationPath(recordedName);
+            if (!isDirectPathInsideFolder(recordedPath)) {
+                return FileResolution.broken(recordedName, recordedPath, "outside the store folder");
+            }
+            if (!Files.exists(recordedPath, LinkOption.NOFOLLOW_LINKS)) {
+                return FileResolution.broken(recordedName, recordedPath, "missing");
+            }
+
+            Path realPath = recordedPath.toRealPath();
+            if (!realPath.getParent().equals(folderReal) || !realPath.startsWith(folderReal)
+                    || !Files.isRegularFile(realPath, LinkOption.NOFOLLOW_LINKS)) {
+                return FileResolution.broken(recordedName, recordedPath, "not a regular file directly in the store folder");
+            }
+            return FileResolution.regular(recordedName, recordedPath, realPath,
+                    Files.isSymbolicLink(recordedPath));
+        } catch (IOException e) {
+            return FileResolution.broken(recordedName, destinationPath(recordedName),
+                    Files.exists(destinationPath(recordedName), LinkOption.NOFOLLOW_LINKS) ? "unreadable" : "missing");
+        }
+    }
+
+    private Path destinationPath(String name) {
+        return storeFolder.toPath().resolve(name).toAbsolutePath().normalize();
+    }
+
+    private boolean isDirectPathInsideFolder(Path path) {
+        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+        return folder.equals(path.getParent());
+    }
+
+    private IntegrityAnalysis analyze(Properties properties) {
+        IntegrityAnalysis result = new IntegrityAnalysis();
+        Map<String, List<Entry>> byRecordedName = new HashMap<>();
+        Map<Path, List<Entry>> byResolvedFile = new HashMap<>();
+        Map<String, List<Entry>> byDerivedName = new HashMap<>();
+
+        for (String description : properties.stringPropertyNames()) {
+            String normalizedDescription = normalize(description);
+            String recordedName = normalize(properties.getProperty(description));
+            String derivedName = nameForIntegrity(normalizedDescription);
+            Entry entry = new Entry(normalizedDescription, recordedName, derivedName, resolve(recordedName));
+            result.entries.add(entry);
+            byRecordedName.computeIfAbsent(recordedName, ignored -> new ArrayList<>()).add(entry);
+            if (entry.resolution.isRegular()) {
+                byResolvedFile.computeIfAbsent(entry.resolution.realPath, ignored -> new ArrayList<>()).add(entry);
+            }
+            byDerivedName.computeIfAbsent(derivedName, ignored -> new ArrayList<>()).add(entry);
+        }
+
+        for (List<Entry> entries : byRecordedName.values()) {
+            if (entries.size() > 1) {
+                result.shared.addAll(entries);
+            }
+        }
+        for (List<Entry> entries : byResolvedFile.values()) {
+            if (entries.size() > 1) {
+                result.shared.addAll(entries);
+            }
+        }
+        for (Entry entry : result.entries) {
+            if (result.shared.contains(entry)) {
+                continue;
+            }
+            if (!entry.resolution.isRegular()) {
+                result.broken.add(entry);
+            } else {
+                try {
+                    if (readLines(entry.recordedName).isEmpty()) {
+                        result.resolved.add(entry);
+                    }
+                } catch (StoreReadException e) {
+                    result.broken.add(entry);
+                }
+            }
+
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            if (entry.misplaced) {
+                result.misplaced.add(entry);
+            }
+            if (byDerivedName.get(entry.derivedName).size() > 1) {
+                result.colliding.add(entry);
+            }
+            if (entry.misplaced && isOccupied(entry, byRecordedName)) {
+                result.occupied.add(entry);
+            }
+        }
+        result.unownedFiles.addAll(findUnownedFiles(byRecordedName.keySet()));
+        return result;
+    }
+
+    private String nameForIntegrity(String description) {
+        String name = activeStrategy.createRuleFileName(description);
+        if (name == null || name.trim().isEmpty()) {
+            throw new StoreInitializationFailedException("RuleViolationFileNameStrategy returned no file name");
+        }
+        return normalize(name);
+    }
+
+    private boolean isOccupied(Entry entry, Map<String, List<Entry>> byRecordedName) {
+        if (entry.recordedName.equals(entry.derivedName)) {
+            return false;
+        }
+        if (byRecordedName.containsKey(entry.derivedName)) {
+            return true;
+        }
+        Path derivedPath = destinationPath(entry.derivedName);
+        return !isDirectPathInsideFolder(derivedPath)
+                || Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private List<String> findUnownedFiles(Set<String> recordedNames) {
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path file : files) {
+                String name = file.getFileName().toString();
+                if (!STORED_RULES_FILE_NAME.equals(name)
+                        && !recordedNames.contains(name)
+                        && Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    result.add(name);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private void repair(Properties properties, IntegrityAnalysis analysis, StoreState state) {
+        boolean changed = false;
+        Set<String> removed = new HashSet<>();
+
+        // Shared entries are deliberately excluded from every repair action.
+        for (Entry entry : analysis.entries) {
+            if (analysis.shared.contains(entry)) {
+                continue;
+            }
+            if (analysis.broken.contains(entry)) {
+                properties.remove(entry.description);
+                removed.add(entry.description);
+                changed = true;
+            } else if (analysis.resolved.contains(entry)) {
+                deleteEntryFile(entry.resolution);
+                properties.remove(entry.description);
+                removed.add(entry.description);
+                changed = true;
+            }
+        }
+
+        for (Entry entry : analysis.entries) {
+            if (removed.contains(entry.description) || analysis.shared.contains(entry)
+                    || analysis.broken.contains(entry) || analysis.resolved.contains(entry)
+                    || !entry.misplaced || analysis.colliding.contains(entry)
+                    || analysis.occupied.contains(entry)) {
+                continue;
+            }
+            moveEntryFile(entry);
+            properties.setProperty(entry.description, entry.derivedName);
+            changed = true;
+        }
+
+        if (changed) {
+            syncProperties(state);
+        }
+    }
+
+    private void moveEntryFile(Entry entry) {
+        Path destination = destinationPath(entry.derivedName);
+        if (!isDirectPathInsideFolder(destination) || Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot repair misplaced entry '%s': destination '%s' is occupied or outside the store folder",
+                    entry.description, entry.derivedName));
+        }
+        try {
+            Files.move(entry.resolution.realPath, destination);
+            if (entry.resolution.isSymbolicLink()) {
+                Files.delete(entry.resolution.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private String normalize(String value) {
+        return value == null ? null : value.replace("\r\n", "\n");
+    }
+
+    private StoreState initializedState() {
+        if (storeState == null || storeState.properties == null) {
+            throw new IllegalStateException("Violation store has not been initialized");
+        }
+        return storeState;
+    }
+
+    private static void deleteQuietly(Path path) {
+        try {
+            Files.deleteIfExists(path);
+        } catch (IOException ignored) {
+            // The original update exception is more useful to callers.
+        }
+    }
+
+    private static class StoreState {
+        private final Object lock = new Object();
+        private final File indexFile;
+        private Properties properties;
+
+        private StoreState(File indexFile) {
+            this.indexFile = indexFile;
+        }
+    }
+
+    private enum IntegrityMode {
+        IGNORE, REPAIR, FAIL
+    }
+
+    private static class FileResolution {
+        private final String recordedName;
+        private final Path recordedPath;
+        private final Path realPath;
+        private final String problem;
+        private final boolean symbolicLink;
+
+        private FileResolution(String recordedName, Path recordedPath, Path realPath, String problem,
+                boolean symbolicLink) {
+            this.recordedName = recordedName;
+            this.recordedPath = recordedPath;
+            this.realPath = realPath;
+            this.problem = problem;
+            this.symbolicLink = symbolicLink;
+        }
+
+        private static FileResolution regular(String recordedName, Path recordedPath, Path realPath,
+                boolean symbolicLink) {
+            return new FileResolution(recordedName, recordedPath, realPath, null, symbolicLink);
+        }
+
+        private static FileResolution broken(String recordedName, Path recordedPath, String problem) {
+            return new FileResolution(recordedName, recordedPath, null, problem, false);
+        }
+
+        private boolean isRegular() {
+            return realPath != null;
+        }
+
+        private boolean isSymbolicLink() {
+            return symbolicLink;
+        }
+
+        private boolean isUnsafeForUpdate() {
+            return problem != null && !("missing".equals(problem) && recordedPath != null
+                    && Files.notExists(recordedPath, LinkOption.NOFOLLOW_LINKS));
+        }
+    }
+
+    private static class Entry {
+        private final String description;
+        private final String recordedName;
+        private final String derivedName;
+        private final FileResolution resolution;
+        private boolean misplaced;
+
+        private Entry(String description, String recordedName, String derivedName, FileResolution resolution) {
+            this.description = description;
+            this.recordedName = recordedName;
+            this.derivedName = derivedName;
+            this.resolution = resolution;
+        }
+    }
+
+    private class IntegrityAnalysis {
+        private final List<Entry> entries = new ArrayList<>();
+        private final List<Entry> broken = new ArrayList<>();
+        private final List<Entry> resolved = new ArrayList<>();
+        private final List<Entry> shared = new ArrayList<>();
+        private final List<Entry> misplaced = new ArrayList<>();
+        private final List<Entry> colliding = new ArrayList<>();
+        private final List<Entry> occupied = new ArrayList<>();
+        private final List<String> unownedFiles = new ArrayList<>();
+
+        private boolean hasProblems() {
+            return !broken.isEmpty() || !resolved.isEmpty() || !shared.isEmpty()
+                    || !misplaced.isEmpty() || !colliding.isEmpty() || !occupied.isEmpty()
+                    || !unownedFiles.isEmpty();
+        }
+
+        private String failureReport() {
+            StringBuilder result = new StringBuilder("Violation store integrity check failed (default.integrity=fail):");
+            appendEntries(result, "broken entries", broken);
+            appendEntries(result, "resolved entries", resolved);
+            appendEntries(result, "shared entries", shared);
+            appendFiles(result, "unowned files", unownedFiles);
+            appendEntries(result, "misplaced entries", misplaced);
+            appendEntries(result, "colliding entries", colliding);
+            appendEntries(result, "occupied entries", occupied);
+            return result.toString();
+        }
+
+        private void appendEntries(StringBuilder result, String heading, List<Entry> entries) {
+            if (entries.isEmpty()) {
+                return;
+            }
